$$
\begin{align*}
&\text{Current block of } J_a(s_1)J^a(s_2)\sim\sum_{S,\ell=S\to\infty}\text{geodesic operator of }S\to\infty\text{ and}\ell\to\infty\text{ with fixed ratio.}
\end{align*}
$$
